<template><view><view v-if="profile?.id" class="coop-profile-card"><view class="coop-profile-title"><view class="coop-profile-avatar">{{ String(profile.name || '店').slice(0, 1) }}</view><view><view class="coop-profile-name">{{ profile.name }}</view><view class="coop-muted">{{ profile.region_text }}</view></view></view><view class="coop-profile-badges"><text>{{ profile.grade_name || '等级未设置' }}</text><text v-if="profile.is_reliable" class="is-reliable">✓ 靠谱认证</text><text v-if="profile.blocked_at" class="is-blocked">已停止合作</text></view><view class="coop-menu-row" @tap="open"><text>门店资料</text><u-icon name="arrow-right" size="14" color="#9aa2ad" /></view><view class="coop-menu-row" @tap="$emit('connection')"><text>ERP 连接与采集进度</text><text>{{ connectionLabel }} ›</text></view><view class="coop-menu-row" @tap="$emit('subscribe')"><text>接收工单通知</text><text>去订阅 ›</text></view></view><view v-if="profile?.blocked_at" class="coop-task-rule">合作已停用：{{ profile.block_reason || '请联系平台核对' }}。历史记录和已形成收益仍保留。</view><view v-if="profile?.id" class="coop-form-section"><view class="coop-section-title">发单权益</view><view class="coop-muted">{{ Number(profile.publisher_until) * 1000 > Date.now() ? '有效期至 ' + coopDate(profile.publisher_until) : config.publishing_required === false ? '本站当前不要求购买发单权益' : '未开通或已到期，购买后有效一个月' }}</view><view class="coop-profile-buy"><text>{{ Number(config.publishing_price) > 0 ? coopMoney(config.publishing_price) + ' / 月' : '价格尚未配置' }}</text><u-button size="small" type="primary" shape="circle" text="购买 / 续期" :disabled="busy || !!profile.blocked_at || Number(config.publishing_price) <= 0" @click="$emit('purchase', 'publishing')" /></view></view><view v-if="profile?.id" class="coop-form-section"><view class="coop-section-title">靠谱商家认证</view><view class="coop-muted">{{ profile.is_reliable ? '有效期至 ' + coopDate(profile.cert_expires_at) : profile.certification_status === 'pending' ? '已支付申请费用，等待平台核验' : '申请后由平台核验，不代表现货或赔付担保' }}</view><view class="coop-profile-buy"><text>{{ Number(config.certification_price) > 0 ? coopMoney(config.certification_price) : '价格尚未配置' }}</text><u-button size="small" shape="circle" text="申请认证" :disabled="busy || !!profile.blocked_at || profile.certification_status === 'pending' || Number(config.certification_price) <= 0" @click="$emit('purchase', 'certification')" /></view></view><CoopTaskSheet :show="visible || onboarding" :title="onboarding ? '完善门店资料' : '门店资料'" :subtitle="onboarding ? '使用当前会员入驻，资料保存后再连接 ERP' : '地区用于同城匹配，ERP 来源地区不会自动覆盖'" :busy="busy" full @close="close"><view class="coop-form-section"><view class="coop-form-column"><text>门店名称</text><u-input v-model="form.name" maxlength="120" placeholder="门店对外名称" :disabled="busy" /></view><view class="coop-form-column"><text>联系人</text><u-input v-model="form.contact_name" maxlength="60" placeholder="实际联系人姓名" :disabled="busy" /></view><view class="coop-form-column"><text>联系电话</text><u-input v-model="form.mobile" type="number" maxlength="20" placeholder="门店联系电话" :disabled="busy" /></view><view class="coop-form-column"><text>门店所在地区</text><CoopRegionFields v-model="region" :disabled="busy" /></view><view class="coop-form-column"><text>详细地址</text><u-textarea v-model="form.address" maxlength="500" placeholder="街道、门牌和楼层" :disabled="busy" /></view><view class="coop-form-column"><text>使用的 ERP</text><picker :range="providerOptions" range-key="name" :value="providerIndex" :disabled="busy" @change="form.provider = providerOptions[Number($event.detail.value)]?.key || ''"><view class="coop-picker-field">{{ providerOptions[providerIndex]?.name || '请选择 ERP' }} ›</view></picker></view></view><view v-if="localError || error" class="coop-inline-error coop-form-error">{{ localError || error }}</view><template #footer><u-button type="primary" shape="circle" text="保存门店资料" :loading="busy" :disabled="busy" @click="submit" /></template></CoopTaskSheet></view></template>
<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { coopDate, coopMoney, type CoopRow } from '../../api/cooperation'
import CoopTaskSheet from './CoopTaskSheet.vue'
import CoopRegionFields from './CoopRegionFields.vue'
const props = withDefaults(defineProps<{ profile: CoopRow; config: CoopRow; providers: CoopRow[]; onboarding?: boolean; busy?: boolean; error?: string }>(), { onboarding: false, busy: false, error: '' })
const emit = defineEmits<{ (event: 'submit', value: CoopRow): void; (event: 'connection' | 'subscribe'): void; (event: 'purchase', purpose: string): void; (event: 'overlay', value: boolean): void }>()
const visible = ref(false), localError = ref(''), form = reactive<CoopRow>({ name: '', contact_name: '', mobile: '', province_id: 0, city_id: 0, district_id: 0, address: '', provider: '' })
const region = computed({ get: () => form, set: value => Object.assign(form, value) }), providerOptions = computed(() => [{ key: '', name: '请选择 ERP' }, ...props.providers]), providerIndex = computed(() => Math.max(0, providerOptions.value.findIndex(item => item.key === form.provider)))
const connectionLabel = computed(() => props.profile.connection?.last_sync_status === 'completed' ? '已同步' : props.profile.connection?.enabled ? '查看进度' : '待接入')
function fill() { Object.assign(form, { name: '', contact_name: '', mobile: '', province_id: 0, city_id: 0, district_id: 0, address: '', provider: '' }, props.profile, { provider: props.profile.provider_requested || props.profile.connection?.provider || '' }); localError.value = '' }
function open() { if (props.busy) return; fill(); visible.value = true; emit('overlay', true) }
function close() { if (props.busy || props.onboarding) return; visible.value = false; emit('overlay', false) }
function submit() { localError.value = ''; if (!form.name.trim() || !form.contact_name.trim()) { localError.value = '请填写门店名称与联系人'; return }; if (!/^1\d{10}$/.test(String(form.mobile))) { localError.value = '请填写有效联系电话'; return }; if (!form.district_id || !String(form.address || '').trim()) { localError.value = '请选择门店省市区并填写详细地址'; return }; if (!form.provider) { localError.value = '请选择使用的 ERP，保存后可继续授权'; return }; emit('submit', Object.fromEntries(['name', 'contact_name', 'mobile', 'province_id', 'city_id', 'district_id', 'address', 'provider'].map(key => [key, form[key]]))) }
watch(() => props.onboarding, value => { if (value) fill() }, { immediate: true })
watch(() => props.busy, (value, old) => { if (!value && old && !props.error && props.profile.id) { visible.value = false; emit('overlay', false) } })
defineExpose({ open, close })
</script>
